import{t as e}from"./modeTest.js";var t={id:`unknown`,emoji:`🌫️`,title:`Не знаю, что чувствую, или пусто`,hint:`так бывает у всех — пусть подскажет тело`,leaves:[{modeId:`detached_protector`,emoji:`😶`,label:`Пусто и ровно, как в вате`,desc:`Чувства будто выключили: внутри тихо, плоско, всё далеко. Само онемение — уже режим: так психика прикрывает от слишком сильной боли.`},{modeId:`detached_self_soother`,emoji:`📱`,label:`Залипаю — лента, еда, сериал`,desc:`Рука сама тянется отвлечься, и время проваливается. Под залипанием обычно прячется чувство, с которым не хочется оставаться наедине.`},{modeId:`vulnerable_child`,emoji:`💧`,label:`Ком в горле, сжимает в груди`,desc:`Так тело держит грусть или страх, которым пока нет слов. Внутри — уязвимая детская часть, которой важно, чтобы кто-то был рядом.`},{modeId:`angry_child`,emoji:`🔥`,label:`Сжаты челюсти, всё раздражает`,desc:`Похоже на злость, которой не дали голоса: задели что-то важное или нарушили границу. Тело злится раньше, чем получается это назвать.`},{modeId:`humiliated_child`,emoji:`🐚`,label:`Хочется сжаться и стать незаметнее`,desc:`Так тело прячет стыд. Под ним — ощущение «со мной что-то не так», которое страшно показать другим.`},{modeId:`avoidant_protector`,emoji:`🐢`,label:`Тяжесть, всё откладываю`,desc:`Сил ни на что нет, дела и разговоры откладываются сами собой. Часто так избегание бережёт от того, к чему страшно подойти.`}]},n={anger:[{modeId:`angry_protector`,emoji:`😡`,label:`Огрызаюсь, чтобы не лезли`,desc:`Колючесть и резкость держат людей подальше от больного места. Такая злость — щит: она охраняет уязвимое внутри, пока к нему не подобрались.`},{modeId:`bully_attack`,emoji:`👊`,label:`Давлю, повышаю голос, иду в атаку`,desc:`Злость переходит в наступление: напор, резкие слова, желание продавить своё. Под бронёй атаки обычно прячется страх собственной слабости или незначимости.`}],critic:[{modeId:`flagellating_oc`,emoji:`😩`,label:`Наказываю себя за промахи`,desc:`Критик звучит словами, а здесь — действия: лишаю себя отдыха и приятного, гоняю себя за любую оплошность. Наказание кажется способом себя исправить, но сил от него только меньше.`}],ok:[{modeId:`pollyanna`,emoji:`🌈`,label:`Всё нормально — и хватит об этом`,desc:`Спокойствие бывает настоящим, а бывает бодрым фасадом, который отгоняет неприятные вопросы. Если тянет отмахнуться от любого разговора о трудном — это он.`}],hurt:[{modeId:`attention_seeker`,emoji:`🌟`,label:`Без отклика — будто меня нет`,desc:`Тянет к вниманию и признанию: когда никто не замечает, внутри становится пусто. За этим стоит настоящая потребность: чтобы заметили и увидели по-настоящему.`}],avoid:[{modeId:`undisciplined_child`,emoji:`🌀`,label:`Бросаю, как только скучно или трудно`,desc:`Интерес гаснет при первом усилии, начатое копится недоделанным. Здесь трудно выдержать скуку и напряжение — тело просто уходит от них.`}]},r=new Map;for(let t of e)for(let e of t.leaves)r.has(e.modeId)||r.set(e.modeId,e);function i(e,t){let n=r.get(e);return t?{...n,...t}:n}function a(e,t){let r=n[e].find(e=>e.modeId===t);return{label:r.label,desc:r.desc}}var o=[{id:`fear`,emoji:`😨`,title:`Страшно, тревожно`,hint:`страх и тревога — сигналы уязвимого внутри`,question:`Про что этот страх?`,leaves:[i(`abandoned_child`),i(`dependent_child`),i(`vulnerable_child`),i(`worrying_oc`),i(`overcontroller`),i(`suspicious_oc`),i(`compulsive_oc`),i(`avoidant_protector`)]},{id:`sad`,emoji:`😢`,title:`Грустно, одиноко`,hint:`грусти нужно присутствие, не решение`,question:`Какая это грусть?`,leaves:[i(`vulnerable_child`),i(`lonely_child`),i(`attention_seeker`,a(`hurt`,`attention_seeker`)),i(`helpless_surrenderer`)]},{id:`anger`,emoji:`😠`,title:`Злюсь, вспыхиваю`,hint:`злость говорит о нарушенной границе или потребности`,question:`Какая это злость?`,leaves:[i(`angry_child`),i(`enraged_child`),i(`angry_protector`,a(`anger`,`angry_protector`)),i(`bully_attack`,a(`anger`,`bully_attack`)),i(`stubborn_child`),i(`impulsive_child`)]},{id:`shame`,emoji:`😳`,title:`Стыд или вина`,hint:`стыд и вина часто звучат чужим голосом`,question:`Кто это говорит внутри?`,leaves:[i(`humiliated_child`),i(`punitive_critic`),i(`guilt_critic`),i(`demanding_critic`),i(`perfectionistic_oc`),i(`flagellating_oc`,a(`critic`,`flagellating_oc`)),i(`compliant_surrenderer`,{label:`Неловко отказать — соглашаюсь`})]},{id:`drained`,emoji:`🥱`,title:`Нет сил, ничего не хочется`,hint:`истощение — тоже сигнал, а не лень`,question:`Как это выглядит?`,leaves:[i(`avoidant_protector`),i(`undisciplined_child`,a(`avoid`,`undisciplined_child`)),i(`helpless_surrenderer`),i(`detached_self_soother`)]},{id:`unknown`,emoji:`🌫️`,title:`Пусто или не пойму, что чувствую`,hint:t.hint,question:`Пусть подскажет тело`,leaves:[...t.leaves]},{id:`above`,emoji:`😎`,title:`На подъёме, выше других`,hint:`за блеском и бронёй обычно прячется страх`,question:`Что за подъём?`,leaves:[i(`self_aggrandiser`),i(`invincible_oc`),i(`manipulative`),i(`predator`),i(`attention_seeker`),i(`bully_attack`)]},{id:`ok`,emoji:`🌿`,title:`Спокойно, хорошо`,hint:`ресурсное состояние — можно побыть в нём`,question:`Настоящее ли это спокойствие?`,leaves:[i(`healthy_adult`),i(`happy_child`),i(`good_parent`),i(`pollyanna`,a(`ok`,`pollyanna`))]}],s=o;function c(e){for(let t of o)for(let n of t.leaves)if(n.modeId===e)return n.label}function l(e){return o.find(t=>t.leaves.some(t=>t.modeId===e))?.id??null}export{t as i,l as n,c as r,s as t};